{"command":"$paths = @(
  "C:\Program Files\Git\bin\bash.exe",
  "C:\Program Files\Git\usr\bin\bash.exe",
  "C:\Windows\System32\bash.exe"
); foreach ($p in $paths) { if (Test-Path $p) { "FOUND: $p" } }; Get-Command bash -ErrorAction SilentlyContinue | Format-List; Get-Command python -ErrorAction SilentlyContinue | Select-Object Source; Get-Command python3 -ErrorAction SilentlyContinue | Select-Object Source; Test-Path "$env:USERPROFILE\.grok\skills"; Test-Path "$env:USERPROFILE\.cursor\skills"","description":"Locate bash and check skills dirs"}

{"command":"@(
  "$env:USERPROFILE\.grok\skills\ai-dev-sop\SKILL.md",
  "$env:USERPROFILE\.cursor\skills\ai-dev-sop\SKILL.md",
  "$env:USERPROFILE\.claude\skills\ai-dev-sop\SKILL.md",
  "$env:USERPROFILE\.agents\skills\ai-dev-sop\SKILL.md"
) | ForEach-Object { if (Test-Path $_) { "OK  $_" } else { "MISSING  $_" } }","description":"Verify installed skill files exist"}
